from decimal import Decimal, ROUND_HALF_UP
import itertools, random
import pricing


def original(cart, customer, coupon=None):
    total = Decimal("0")
    lines = []
    for item in cart:
        p = Decimal(str(item["price"]))
        q = item["qty"]
        if q <= 0:
            continue
        if customer.get("tier") == "silver":
            if item.get("category") == "books":
                line = p * q
                if q >= 10:
                    line = line * Decimal("0.9")
                line = line * Decimal("0.95")
            else:
                line = p * q
                if q >= 10:
                    line = line * Decimal("0.9")
                line = line * Decimal("0.95")
        elif customer.get("tier") == "platinum":
            if item.get("category") == "books":
                line = p * q
                if q >= 10:
                    line = line * Decimal("0.9")
                line = line * Decimal("0.80")
            else:
                line = p * q
                if q >= 10:
                    line = line * Decimal("0.9")
                line = line * Decimal("0.80")
        else:
            if item.get("category") == "books":
                line = p * q
                if q >= 10:
                    line = line * Decimal("0.9")
            else:
                line = p * q
                if q >= 10:
                    line = line * Decimal("0.9")
        if item.get("category") == "books":
            tax = Decimal("0.07")
        elif item.get("category") == "food":
            tax = Decimal("0.07")
        else:
            tax = Decimal("0.19")
        line = line.quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)
        t = (line * tax).quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)
        lines.append({"sku": item["sku"], "net": line, "tax": t})
        total = total + line + t
    if coupon is not None:
        if coupon == "WELCOME5":
            if total >= Decimal("20"):
                total = total - Decimal("5")
        elif coupon == "HALFSHIP":
            pass
        elif coupon.startswith("PCT"):
            pct = int(coupon[3:])
            if pct > 30:
                pct = 30
            total = total - (total * pct / 100).quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)
        else:
            raise ValueError("unknown coupon")
    if total < 0:
        total = Decimal("0")
    return {"lines": lines, "total": total.quantize(Decimal("0.01"))}


prices = ["0", "0.01", "0.005", "1", "3.33", "9.99", "12.99", "19.995", "20", "99.999", "123.456", 10, 12.345]
qtys = [-5, 0, 1, 2, 9, 10, 11, 50]
cats = [None, "books", "food", "toys", "BOOKS", ""]
tiers = [None, "silver", "platinum", "bronze", "gold", ""]
coupons = [None, "WELCOME5", "HALFSHIP", "PCT0", "PCT5", "PCT30", "PCT99", "PCT7"]

checked = 0
for price, qty, cat, tier, coupon in itertools.product(prices, qtys, cats, tiers, coupons):
    item = {"sku": "S", "price": price, "qty": qty}
    if cat is not None:
        item["category"] = cat
    customer = {} if tier is None else {"tier": tier}
    a = original([item], customer, coupon)
    b = pricing.checkout([item], customer, coupon)
    assert a == b, (item, customer, coupon, a, b)
    checked += 1

# Multi-item carts, including mixed quantities/categories and duplicate SKUs.
rng = random.Random(1234)
for _ in range(5000):
    cart = []
    for i in range(rng.randint(0, 6)):
        item = {"sku": f"SKU{i}", "price": rng.choice(prices), "qty": rng.choice(qtys)}
        cat = rng.choice(cats)
        if cat is not None:
            item["category"] = cat
        cart.append(item)
    tier = rng.choice(tiers)
    customer = {} if tier is None else {"tier": tier}
    coupon = rng.choice(coupons)
    a = original(cart, customer, coupon)
    b = pricing.checkout(cart, customer, coupon)
    assert a == b, (cart, customer, coupon, a, b)
    checked += 1

# Gold: must be exactly a 12% discount applied after the bulk discount, like others.
for price, qty, cat in itertools.product(prices, qtys, cats):
    item = {"sku": "S", "price": price, "qty": qty}
    if cat is not None:
        item["category"] = cat
    if qty <= 0:
        assert pricing.price_line(item, {"tier": "gold"}) is None
        continue
    expected = original([item], {"tier": "silver"})
    # compare gold against the same formula with 0.88
    p = Decimal(str(price)); q = qty
    net = p * q
    if q >= 10:
        net = net * Decimal("0.9")
    net = net * Decimal("0.88")
    rate = Decimal("0.07") if cat in ("books", "food") else Decimal("0.19")
    net = net.quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)
    tax = (net * rate).quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)
    assert pricing.price_line(item, {"tier": "gold"}) == {"sku": "S", "net": net, "tax": tax}

# Unknown coupon still raises.
try:
    pricing.checkout([], {}, "NOPE")
except ValueError:
    pass
else:
    raise AssertionError("unknown coupon did not raise")

print(f"ok differential equivalence on {checked} cases; gold tier verified")
